public class ReservationQueue
{
    private readonly Dictionary<string, Queue<Member>> _bookReservations = new();

    public void Reserve(string isbn, Member member)
    {
        if (!_bookReservations.ContainsKey(isbn))
            _bookReservations[isbn] = new Queue<Member>();
        _bookReservations[isbn].Enqueue(member);
    }

    public Member? GetNextReserved(string isbn)
    {
        return _bookReservations.TryGetValue(isbn, out var queue) && queue.Count > 0
            ? queue.Dequeue()
            : null;
    }
}

public interface IFinePolicy
{
    decimal CalculateFine(Book book, DateTime returnDate);
}

public class StandardFinePolicy : IFinePolicy
{
    public decimal CalculateFine(Book book, DateTime returnDate)
    {
        if (!book.DueDate.HasValue || returnDate <= book.DueDate.Value) return 0;
        int daysLate = (returnDate - book.DueDate.Value).Days;
        return daysLate * 0.5m;
    }
}

public class PremiumMemberFinePolicy : IFinePolicy
{
    public decimal CalculateFine(Book book, DateTime returnDate)
    {
        if (!book.DueDate.HasValue || returnDate <= book.DueDate.Value) return 0;
        int daysLate = (returnDate - book.DueDate.Value).Days;
        return daysLate * 0.25m; // half the standard fine
    }
}
